'use cache'

import { cacheLife, cacheTag } from 'next/cache'
import { getPosts } from '@/lib/api'

export default async function Home() {
  cacheLife('hours') // 1 hour cache duration
  cacheTag('posts') // Tag for on-demand invalidation via revalidateTag('posts')

  const posts = await getPosts()

  return (
    <main>
      <h1>Blog Posts</h1>
      <ul>
        {posts.map((post) => (
          <li key={post.id}>
            <strong>{post.title}</strong> — {post.author}
          </li>
        ))}
      </ul>
    </main>
  )
}

